import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            sum += a[i];
        }
        long average = sum / n;
        // Prefix surpluses P. total may wrap past 2^63, but both costs are below 2^64,
        // so the wrapped differences read as unsigned are exact.
        long prefix = 0, total = 0, low = 0, high = 0;
        for (long v : a) {
            prefix += v - average;
            total += prefix;
            low = Math.min(low, prefix);
            high = Math.max(high, prefix);
        }
        long clockwise = total - n * low, counterclockwise = n * high - total;
        long answer = Long.compareUnsigned(clockwise, counterclockwise) <= 0 ? clockwise : counterclockwise;
        System.out.println(Long.toUnsignedString(answer));
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	sum := 0
	for i := range a {
		a[i] = nextInt()
		sum += a[i]
	}
	average := sum / n
	// Prefix surpluses P. total may wrap past 2^63, but both costs are below 2^64,
	// so the wrapped differences read as unsigned are exact.
	prefix, total, low, high := 0, 0, 0, 0
	for _, v := range a {
		prefix += v - average
		total += prefix
		low = min(low, prefix)
		high = max(high, prefix)
	}
	clockwise := uint64(total - n*low)
	counterclockwise := uint64(n*high - total)
	os.Stdout.WriteString(strconv.FormatUint(min(clockwise, counterclockwise), 10) + "\n")
}
